import{_ as t,o,c as i,a0 as n}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"The select list opens the init for a repository with no ticket","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0082-the-select-list-opens-the-init-for-a-repository-with-no-ticket.md","filePath":"adr/0082-the-select-list-opens-the-init-for-a-repository-with-no-ticket.md"}'),s={name:"adr/0082-the-select-list-opens-the-init-for-a-repository-with-no-ticket.md"};function a(r,e,h,c,d,l){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="the-select-list-opens-the-init-for-a-repository-with-no-ticket" tabindex="-1">The select list opens the init for a repository with no ticket <a class="header-anchor" href="#the-select-list-opens-the-init-for-a-repository-with-no-ticket" aria-label="Permalink to &quot;The select list opens the init for a repository with no ticket&quot;">​</a></h1><p>Status: accepted.</p><p>The init (ADR 0075) opens from the Ticket list: group by repository and press <code>i</code> on the repository&#39;s Group header. A repository the factory has never seen carries no ticket and no source, so it never stands in the list, and its header never appears. The operator who has just pointed the factory at a new repository has no way to start the init. This is the bootstrap gap. We decided the main view carries an <code>o</code> key that opens the repository select list. The list reads the operator&#39;s GitHub account and the organizations the account belongs to, in one GraphQL read on the ambient <code>gh</code> credentials. The list is a searchable row of the shared decision region. Enter on a row resolves the repository&#39;s local checkout from the <code>repos</code> table or the conventional path, runs the init&#39;s plan, and opens the same confirmation panel the <code>i</code> path opens. The plane never clones. A repository without a local checkout is refused with the path the act needs.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li>An owner/name text entry, like the consultation&#39;s repository field. Rejected: the read needs a live identity to stand on, and the entry would accept a repository the operator does not own or a typo, only to fail the plan.</li><li>The read on each repository&#39;s host. Rejected: the ambient credentials are one identity. The fixed host is <code>github.com</code>, the host the ambient <code>gh</code> identity stands on.</li><li>A clone step beside the refusal. Rejected: a clone is its own act, with its own path choice and its own confirmation. The select list keeps to the bootstrap: it finds the repository, and it runs the init the operator already confirmed the shape of.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The <code>o</code> key stands in the key guide, and the guide&#39;s Ticket section and the Control plane section carry its rows.</li><li>The read is capped at the first 100 repositories of the account and of each of the first 20 organizations, in the API&#39;s order.</li><li>The read runs once when the panel opens. The panel carries no refresh key.</li><li>The ambient identity is the identity the operator gave <code>gh</code>. The plane asks no credential of its own.</li><li>The refusal names the expected checkout path, so the operator can <code>git clone</code> to it and press Enter again.</li></ul>',7)])])}const f=t(s,[["render",a]]);export{u as __pageData,f as default};
